def simulate_bank_transaction():
    account_type = input("Enter account type (checking or savings): ").lower()
    transaction_type = input("Enter transaction type (deposit or withdrawal): ").lower()

    if account_type == "checking":
        if transaction_type == "withdrawal":
            amount = float(input("Enter amount: $"))
            if amount > 1000:
                fee = 5
                new_balance = amount - amount - fee
            else:
                new_balance = amount
        else:
            new_balance = float(input("Enter amount: $"))
    elif account_type == "savings":
        if transaction_type == "withdrawal":
            amount = float(input("Enter amount: $"))
            if amount > 500:
                fee = 3
                new_balance = amount - amount - fee
            else:
                new_balance = amount
        else:
            new_balance = float(input("Enter amount: $"))
    else:
        print("Invalid account type. Please try again.")
        return

    print(f"New balance: ${new_balance:.2f}")

simulate_bank_transaction()
